input.content:
{
  "skill_name": "weekly-report",
  "evals": [
    {
      "id": 1,
      "query": "帮我整理一下这周的周报：完成了搜索接口上线、修复登录超时；下周计划灰度排序算法、推进权限重构。",
      "should_trigger": true,
      "expected_output": "按成果/风险/下周安排三部分输出的中文周报，条目结果导向，缺省周次与汇报人用默认值。"
    },
    {
      "id": 2,
      "query": "把本周工作和下周计划写成一份周报，发给主管。",
      "should_trigger": true,
      "expected_output": "三段式周报，风险由输入推导，无风险时明说而非编造。"
    },
    {
      "id": 3,
      "query": "本周挺忙的，帮我把这些零散记录整理成本周总结。",
      "should_trigger": true,
      "expected_output": "归纳为成果/风险/下周安排，模糊处标注待补充而非虚构。"
    },
    {
      "id": 4,
      "query": "帮我写一份本月的月度经营分析报告。",
      "should_trigger": false,
      "expected_output": "月报不属于周报技能范围，除非用户明确要求套用周报格式。"
    },
    {
      "id": 5,
      "query": "复盘一下昨天那次线上事故，找出根因和改进项。",
      "should_trigger": false,
      "expected_output": "事故复盘应走事件复盘流程，不是按周汇总。"
    }
  ]
}

